#include <bits/stdc++.h>
using namespace std;

class MedianFinder {
    priority_queue<int> lower;                             // smaller half
    priority_queue<int, vector<int>, greater<int>> upper;  // larger half
public:
    void addNum(int num) {
        lower.push(num);
        upper.push(lower.top()); lower.pop();
        if (upper.size() > lower.size()) {
            lower.push(upper.top()); upper.pop();
        }
    }
    double findMedian() {
        if (lower.size() > upper.size()) return lower.top();
        return (lower.top() + upper.top()) / 2.0;
    }
};

